// ============================================================================
// lib/zusia/questions.ts
// The question bank used by Trening, Test (all tasks) and as few-shot
// context for the AI generator. Sources: exercises in the student book
// (answer keys worked out from the lesson text – the book photos have no key),
// the 2017 olympiad first-stage test (updated where rules have changed) and
// ZUSia's own questions built from the theory in lib/zusia/theory.ts.
// ============================================================================
import type { LessonId, Question } from "./types";

let counter = 0;
const nextId = (lesson: LessonId) => `${lesson}-q${String(++counter).padStart(3, "0")}`;

function single(
  lesson: LessonId,
  prompt: string,
  options: string[],
  correct: number,
  explanation: string,
  source = "ZUSia"
): Question {
  return { id: nextId(lesson), lesson, type: "single", prompt, options, correct: [correct], explanation, source };
}

function multi(
  lesson: LessonId,
  prompt: string,
  options: string[],
  correct: number[],
  explanation: string,
  source = "ZUSia"
): Question {
  return { id: nextId(lesson), lesson, type: "multi", prompt, options, correct, explanation, source };
}

function tf(lesson: LessonId, prompt: string, isTrue: boolean, explanation: string, source = "ZUSia"): Question {
  return { id: nextId(lesson), lesson, type: "tf", prompt, correct: [isTrue ? 1 : 0], explanation, source };
}

function open(lesson: LessonId, prompt: string, explanation: string, source = "podręcznik"): Question {
  return { id: nextId(lesson), lesson, type: "open", prompt, explanation, source };
}

